// Demonstrates runtime polymorphism using an abstract class
abstract class Shape {
    abstract double area();
}

class Circle extends Shape {
    private double radius;
    Circle(double r) { radius = r; }
    double area() { return Math.PI * radius * radius; }
}

class Rectangle extends Shape {
    private double width, height;
    Rectangle(double w, double h) { width = w; height = h; }
    double area() { return width * height; }
}

public class Main {
    public static void main(String[] args) {
        Shape s1 = new Circle(5);
        Shape s2 = new Rectangle(4, 6);
        System.out.println("Circle area: " + s1.area());
        System.out.println("Rectangle area: " + s2.area());
    }
}

// Shows both automatic widening and manual narrowing
public class CastingExample {
    public static void main(String[] args) {
        // Widening: byte → int → long → float → double (automatic)
        byte b = 10;
        int i = b;        // OK
        double d = i;     // OK

        // Narrowing: must cast explicitly
        double large = 123.456;
        int small = (int) large;  // Truncates to 123
        byte tiny = (byte) small; // May overflow if value > 127

        System.out.println("Original: " + large);
        System.out.println("After narrowing: " + tiny);
    }
}

