// Pseudocode-inspired implementation: Find and remove duplicates
public static void removeDuplicates(ArrayList<Integer> list) {
    // Step 1: Create a new list to store unique elements
    ArrayList<Integer> unique = new ArrayList<>();
    // Step 2: Iterate through original list
    for (Integer item : list) {
        // Step 3: Add only if not already present
        if (!unique.contains(item)) {
            unique.add(item);
        }
    }
    // Step 4: Clear and refill original list
    list.clear();
    list.addAll(unique);
}

// Helper method to check if a card can be played
public boolean canPlayCard(Card card, Card topCard) {
    // Match suit or rank, or card is an Eight
    return card.getSuit().equals(topCard.getSuit()) ||
           card.getRank().equals(topCard.getRank()) ||
           card.getRank().equals("8");
}

// Main method using helper
public ArrayList<Card> getPlayableCards(ArrayList<Card> hand, Card topCard) {
    ArrayList<Card> playable = new ArrayList<>();
    for (Card card : hand) {
        if (canPlayCard(card, topCard)) {
            playable.add(card);
        }
    }
    return playable;
}

// Step 1: Simple utility method
public static int findMinIndex(ArrayList<Integer> list, int start) {
    int minIndex = start;
    for (int i = start + 1; i < list.size(); i++) {
        if (list.get(i) < list.get(minIndex)) {
            minIndex = i;
        }
    }
    return minIndex;
}

// Step 2: Build selection sort using the utility
public static void selectionSort(ArrayList<Integer> list) {
    for (int i = 0; i < list.size(); i++) {
        int minIndex = findMinIndex(list, i);
        Collections.swap(list, i, minIndex);
    }
}

import java.util.ArrayList;

public class SelectionSort {
    public static void selectionSort(ArrayList<Integer> list) {
        int n = list.size();
        for (int i = 0; i < n - 1; i++) {
            int minIndex = i;
            for (int j = i + 1; j < n; j++) {
                if (list.get(j) < list.get(minIndex)) {
                    minIndex = j;
                }
            }
            // Swap elements
            int temp = list.get(i);
            list.set(i, list.get(minIndex));
            list.set(minIndex, temp);
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<>();
        nums.add(64);
        nums.add(25);
        nums.add(12);
        nums.add(22);
        nums.add(11);

        selectionSort(nums);
        System.out.println(nums); // Output: [11, 12, 22, 25, 64]
    }
}

