import java.util.ArrayList;

public class ReverseList {
    // Main method breaks problem into steps
    public static void reverseList(ArrayList<String> list) {
        int left = 0;
        int right = list.size() - 1;
        while (left < right) {
            swap(list, left, right);
            left++;
            right--;
        }
    }

    // Helper method: swaps two elements
    private static void swap(ArrayList<String> list, int i, int j) {
        String temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
    }

    public static void main(String[] args) {
        ArrayList<String> words = new ArrayList<>();
        words.add("apple");
        words.add("banana");
        words.add("cherry");

        reverseList(words);
        System.out.println(words); // Output: [cherry, banana, apple]
    }
}

