// Instead of printing every loop iteration:
public class ArrayProcessor {
    public static int findMax(int[] arr) {
        if (arr.length == 0) return Integer.MIN_VALUE;

        int max = arr[0];
        // Log only key states
        System.out.println("Initial max: " + max);

        for (int i = 1; i < arr.length; i++) {
            if (arr[i] > max) {
                max = arr[i];
                // Log only when max changes
                System.out.println("New max at index " + i + ": " + max);
            }
        }
        return max;
    }
}

