// Comparing String vs StringBuilder for repeated concatenation
public class StringBuilderDemo {
    public static void main(String[] args) {
        // Inefficient with String (creates many intermediate objects)
        String str = "";
        for (int i = 0; i < 5; i++) {
            str += i; // Avoid in loops!
        }

        // Efficient with StringBuilder
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 5; i++) {
            sb.append(i);
        }
        String result = sb.toString();

        System.out.println("Result: " + result); // "01234"

        // StringBuilder also supports insert and delete
        sb.insert(0, "Start-");
        sb.delete(sb.length() - 1, sb.length()); // remove last char
        System.out.println("Modified: " + sb.toString()); // "Start-0123"
    }
}

