        int[] copy = original.clone();

        Arrays.sort(original);
        System.out.println("Sorted: " + Arrays.toString(original)); // [1, 2, 5, 8, 9]

        boolean areEqual = Arrays.equals(original, copy);
        System.out.println("Arrays equal after sort? " + areEqual); // false

