import java.util.Arrays;

public class SortSearchExample {
    public static void main(String[] args) {
        int[] scores = {88, 95, 72, 100, 64};

        // Sort the array
        Arrays.sort(scores);
        System.out.println("Sorted: " + Arrays.toString(scores));

        // Search for a value
        int target = 95;
        int pos = Arrays.binarySearch(scores, target);
        if (pos >= 0) {
            System.out.println(target + " found at index " + pos);
        } else {
            System.out.println(target + " not found");
        }
    }
}

import java.util.Arrays;

public class CopyArrayExample {
    public static void main(String[] args) {
        int[] original = {1, 2, 3, 4, 5};

        // Copy entire array with new length
        int[] copy1 = Arrays.copyOf(original, original.length);

        // Copy a range (from index 1 to 4)
        int[] copy2 = Arrays.copyOfRange(original, 1, 4);

        System.out.println("Original: " + Arrays.toString(original));
        System.out.println("Full copy: " + Arrays.toString(copy1));
        System.out.println("Range copy: " + Arrays.toString(copy2));
        // Output:
        // Original: [1, 2, 3, 4, 5]
        // Full copy: [1, 2, 3, 4, 5]
        // Range copy: [2, 3, 4]
    }
}

