import java.io.*;

public class MarkResetExample {
    public static void main(String[] args) throws Exception {
        InputStream input = null;
        try {
            input = new FileInputStream("Text.txt");
            System.out.println("First char: " + (char) input.read()); // 'G'
            System.out.println("Second char: " + (char) input.read()); // 'e'

            // Mark current position (after reading 2 chars)
            input.mark(10); // Allow up to 10 bytes to be read before mark becomes invalid

            System.out.println("Third char: " + (char) input.read()); // 'e'
            System.out.println("Fourth char: " + (char) input.read()); // 'k'

            // Reset back to marked position
            input.reset();
            System.out.println("After reset: " + (char) input.read()); // 'e' again
        } finally {
            if (input != null) {
                input.close();
            }
        }
    }
}

