public class IterationExample {
    public static int factorial(int n) {
        int result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(factorial(5)); // Output: 120
    }
}

public class ArraySum {
    public static int sum(int[] arr, int index) {
        if (index >= arr.length) { // base case
            return 0;
        }
        return arr[index] + sum(arr, index + 1); // recursive step
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        System.out.println(sum(numbers, 0)); // Output: 15
    }
}

public class Factorial {
    public static int factorial(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Factorial undefined for negative numbers");
        }
        if (n == 0 || n == 1) { // base case
            return 1;
        }
        return n * factorial(n - 1); // recursive case
    }

    public static void main(String[] args) {
        System.out.println(factorial(5)); // Output: 120
    }
}

public class ArraySum {
    public static int sum(int[] arr, int index) {
        if (index >= arr.length) { // base case: past last element
            return 0;
        }
        return arr[index] + sum(arr, index + 1); // add current and recurse
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        System.out.println(sum(numbers, 0)); // Output: 15
    }
}

public class ReversePrint {
    public static void printReverse(int n) {
        if (n <= 0) { // base case
            return;
        }
        printReverse(n - 1); // recurse first
        System.out.println(n); // print on the way back up
    }

    public static void main(String[] args) {
        printReverse(5); // Output: 1 2 3 4 5 (each on new line)
    }
}

public class Student {
    private String id;
    private int age;

    public String getId() {
        return id;
    }

    public void setId(String id) {
        if (id != null && id.matches("\\d{6}")) {
            this.id = id;
        } else {
            throw new IllegalArgumentException("ID must be 6 digits");
        }
    }

    public int getAge() {
        return age;
    }

    public void setAge(int age) {
        if (age >= 0 && age <= 150) {
            this.age = age;
        } else {
            throw new IllegalArgumentException("Invalid age");
        }
    }
}

public class BankAccount {
    private double balance;
    private String accountNumber;

    public BankAccount(String accountNumber) {
        this.accountNumber = accountNumber;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    public boolean withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            return true;
        }
        return false;
    }

    public double getBalance() {
        return balance;
    }

    public String getAccountNumber() {
        return accountNumber;
    }
}

public class Product {
    private String name;
    private double price;
    private int quantity;

    public Product(String name, double price, int quantity) {
        this.name = name;
        setPrice(price);
        setQuantity(quantity);
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        if (price >= 0) {
            this.price = price;
        }
    }

    public int getQuantity() {
        return quantity;
    }

    public void setQuantity(int quantity) {
        if (quantity >= 0) {
            this.quantity = quantity;
        }
    }

    public double getTotalValue() {
        return price * quantity;
    }
}
